Object.assign(SNIP,{});PRESET_NOTES["l20"]={"Ví dụ: Cây lời gọi của giai thừa": "Cây chỉ là một đường thẳng: mỗi lời gọi sinh đúng một lời gọi con. Đi xuống tới giaiThua(1) rồi các giá trị trả về lần lượt “nổi” lên: 1, 2, 6, 24, 120.", "Ví dụ: Cây lời gọi của fib(5)": "15 lời gọi cho fib(5). Đếm xem fib(2) xuất hiện mấy lần trong cây: mỗi lần là tính lại từ đầu cùng một việc. Độ sâu chỉ 5 tầng dù có 15 lời gọi.", "Ví dụ: Lũy thừa nhanh bằng chia đôi": "aⁿ = (a^(n/2))², nhân thêm a nếu n lẻ. Mỗi lời gọi chỉ gọi một lần với n / 2, nên chỉ có khoảng log₂ n lời gọi: 3¹³ chỉ cần 5 lời gọi thay vì 13 phép nhân.", "Ví dụ: Tháp Hà Nội với 3 đĩa": "Mỗi lời gọi chuyen(n, …) sinh hai lời gọi chuyen(n − 1, …). Với 3 đĩa có 7 lần chuyển (2³ − 1). Nhìn cây để thấy dòng in được thực hiện giữa hai lời gọi con.", "Lỗi: thiếu điều kiện dừng": "Không có điều kiện dừng nên n giảm mãi: 5, 4, …, 0, −1, −2… Trình mô phỏng dừng khi ngăn xếp vượt 3 000 tầng và báo lỗi tràn ngăn xếp."};EX_HINTS["l20"]=[["Điều kiện dừng: n chỉ có một chữ số (n < 10) thì tổng chính là n.", "n % 10 là chữ số cuối, n / 10 là phần còn lại."], ["Mỗi lời gọi chỉ gọi một lần với b / 2: khoảng 60 lời gọi cho b = 10¹⁸.", "Lấy mod sau mỗi phép nhân: hai số < 10⁹ nhân nhau < 10¹⁸, vừa long long. Điều kiện dừng trả về 1 % m (khi m = 1 thì kết quả là 0)."], ["Số bước là 2ⁿ − 1, tính bằng (1 << n) − 1.", "Khi chuyển n − 1 đĩa từ tu sang qua, cọc den đóng vai trung gian; và ngược lại ở lần gọi thứ hai."]];
/* ===================== BÀI 20 · Ôn đệ quy: điều kiện dừng và cây lời gọi ===================== */
/* Bài 20 · Ôn đệ quy: điều kiện dừng và cây lời gọi
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR20=[{label:"Ví dụ: Cây lời gọi của giai thừa",input:"",code:"#include <iostream>\nusing namespace std;\n\nlong long giaiThua(int n) {\n    if (n <= 1) return 1;\n    return n * giaiThua(n - 1);\n}\n\nint main() {\n    cout << giaiThua(5) << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"def giaiThua(n):\n    if n <= 1:\n        return 1\n    return n * giaiThua(n - 1)\n\nprint(giaiThua(5))"},cs:{code:"using System;\n\nclass Program\n{\n    static long GiaiThua(int n)\n    {\n        if (n <= 1) return 1;\n        return n * GiaiThua(n - 1);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(GiaiThua(5));\n    }\n}",note:"Cây chỉ là một đường thẳng: mỗi lời gọi sinh đúng một lời gọi con. Đi xuống tới GiaiThua(1) rồi các giá trị trả về lần lượt “nổi” lên: 1, 2, 6, 24, 120.",viz:[{type:"calls"}]}},{label:"Ví dụ: Cây lời gọi của fib(5)",input:"",code:"#include <iostream>\nusing namespace std;\n\nint fib(int n) {\n    if (n <= 1) return n;\n    return fib(n - 1) + fib(n - 2);\n}\n\nint main() {\n    cout << fib(5) << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"def fib(n):\n    if n <= 1:\n        return n\n    return fib(n - 1) + fib(n - 2)\n\nprint(fib(5))"},cs:{code:"using System;\n\nclass Program\n{\n    static int Fib(int n)\n    {\n        if (n <= 1) return n;\n        return Fib(n - 1) + Fib(n - 2);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Fib(5));\n    }\n}",note:"15 lời gọi cho Fib(5). Đếm xem Fib(2) xuất hiện mấy lần trong cây: mỗi lần là tính lại từ đầu cùng một việc. Độ sâu chỉ 5 tầng dù có 15 lời gọi.",viz:[{type:"calls"}]}},{label:"Ví dụ: Lũy thừa nhanh bằng chia đôi",input:"",code:"#include <iostream>\nusing namespace std;\n\nlong long luyThua(long long a, int n) {\n    if (n == 0) return 1;\n    long long nua = luyThua(a, n / 2);\n    if (n % 2 == 0) return nua * nua;\n    return nua * nua * a;\n}\n\nint main() {\n    cout << luyThua(3, 13) << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"def luyThua(a, n):\n    if n == 0:\n        return 1\n    nua = luyThua(a, n // 2)\n    if n % 2 == 0:\n        return nua * nua\n    return nua * nua * a\n\nprint(luyThua(3, 13))"},cs:{code:"using System;\n\nclass Program\n{\n    static long LuyThua(long a, int n)\n    {\n        if (n == 0) return 1;\n        long nua = LuyThua(a, n / 2);\n        if (n % 2 == 0) return nua * nua;\n        return nua * nua * a;\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(LuyThua(3, 13));\n    }\n}",note:"aⁿ = (a^(n/2))², nhân thêm a nếu n lẻ. Mỗi lời gọi chỉ gọi một lần với n / 2, nên chỉ có khoảng log₂ n lời gọi: 3¹³ chỉ cần 5 lời gọi thay vì 13 phép nhân.",viz:[{type:"calls"}]}},{label:"Ví dụ: Tháp Hà Nội với 3 đĩa",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid chuyen(int n, char tu, char den, char qua) {\n    if (n == 0) return;\n    chuyen(n - 1, tu, qua, den);\n    cout << \"Dia \" << n << \": \" << tu << \" -> \" << den << \"\\n\";\n    chuyen(n - 1, qua, den, tu);\n}\n\nint main() {\n    chuyen(3, 'A', 'C', 'B');\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"def chuyen(n, tu, den, qua):\n    if n == 0:\n        return\n    chuyen(n - 1, tu, qua, den)\n    print(f\"Dia {n}: {tu} -> {den}\")\n    chuyen(n - 1, qua, den, tu)\n\nchuyen(3, \"A\", \"C\", \"B\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Chuyen(int n, char tu, char den, char qua)\n    {\n        if (n == 0) return;\n        Chuyen(n - 1, tu, qua, den);\n        Console.WriteLine(\"Dia \" + n + \": \" + tu + \" -> \" + den);\n        Chuyen(n - 1, qua, den, tu);\n    }\n\n    static void Main()\n    {\n        Chuyen(3, 'A', 'C', 'B');\n    }\n}",note:"Mỗi lời gọi Chuyen(n, …) sinh hai lời gọi Chuyen(n − 1, …). Với 3 đĩa có 7 lần chuyển (2³ − 1). Nhìn cây để thấy dòng in được thực hiện giữa hai lời gọi con.",viz:[{type:"calls"}]}},{label:"Lỗi: thiếu điều kiện dừng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tong(int n) {\n    return n + tong(n - 1);    // quên: if (n == 0) return 0;\n}\n\nint main() {\n    cout << tong(5) << \"\\n\";\n    return 0;\n}",py:{code:"def tong(n):\n    return n + tong(n - 1)    # quên: if n == 0: return 0\n\nprint(tong(5))",note:"Không có điều kiện dừng nên n giảm mãi: 5, 4, …, 0, −1, −2… Python dừng chương trình khi đệ quy vượt khoảng 1 000 tầng và báo RecursionError."},cs:{code:"using System;\n\nclass Program\n{\n    static int Tong(int n)\n    {\n        return n + Tong(n - 1);    // quên: if (n == 0) return 0;\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Tong(5));\n    }\n}",note:"Không có điều kiện dừng nên n giảm mãi: 5, 4, …, 0, −1, −2… Trình mô phỏng dừng khi ngăn xếp vượt 5 000 tầng và báo lỗi tràn ngăn xếp (StackOverflow). Trên .NET thật, lỗi này làm chương trình dừng hẳn, không bắt được bằng try/catch."}}];
