makeEx2(document.getElementById("ex-l20"),sim20,[{t:"Tổng chữ số",d:"Đầu vào: một số nguyên n (0 ≤ n ≤ 10^18). Đầu ra: tổng các chữ số của n. Viết bằng hàm đệ quy tongChuSo.",tests:[{in:"12345",out:"15"},{in:"0",out:"0"},{in:"1000000000000000000",out:"1"},{in:"999999999999999999",out:"162"}],start:"#include <iostream>\nusing namespace std;\n\nint tongChuSo(long long n) {\n    // điều kiện dừng? bước đệ quy: chữ số cuối + tổng chữ số của phần còn lại\n    return 0;\n}\n\nint main() {\n    long long n;\n    cin >> n;\n    cout << tongChuSo(n) << \"\\n\";\n    return 0;\n}",need:/int\s+tongChuSo\s*\([^)]*\)\s*\{[\s\S]*\btongChuSo\s*\([\s\S]*\}[\s\S]*int\s+main/,needMsg:"Hãy viết tongChuSo bằng đệ quy (hàm gọi chính nó).",py:{start:"def tongChuSo(n):\n    # điều kiện dừng? bước đệ quy: chữ số cuối + tổng chữ số của phần còn lại\n    return 0\n\nn = int(input())\nprint(tongChuSo(n))",hints:["Điều kiện dừng: n chỉ có một chữ số (n < 10) thì tổng chính là n.","n % 10 là chữ số cuối, n // 10 là phần còn lại."],needMsg:"Hãy viết tongChuSo bằng đệ quy (hàm gọi chính nó).",need:/def\s+tongChuSo\s*\([^)]*\)\s*:[\s\S]*\btongChuSo\s*\([\s\S]*\btongChuSo\s*\(/},cs:{start:"using System;\n\nclass Program\n{\n    static long TongChuSo(long n)\n    {\n        // điều kiện dừng? bước đệ quy: chữ số cuối + tổng chữ số của phần còn lại\n        return 0;\n    }\n\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        Console.WriteLine(TongChuSo(n));\n    }\n}",d:"Đầu vào: một số nguyên n (0 ≤ n ≤ 10^18). Đầu ra: tổng các chữ số của n. Viết bằng hàm đệ quy TongChuSo.",hints:["Điều kiện dừng: n chỉ có một chữ số (n < 10) thì tổng chính là n.","n % 10 là chữ số cuối, n / 10 là phần còn lại."],needMsg:"Hãy viết TongChuSo bằng đệ quy (hàm gọi chính nó).",need:/static\s+\w+\s+TongChuSo\s*\([^)]*\)\s*\{[\s\S]*\bTongChuSo\s*\([\s\S]*\}[\s\S]*static\s+void\s+Main/}},{t:"Lũy thừa theo modulo",d:"Đầu vào: ba số nguyên a, b, m (0 ≤ a ≤ 10^9, 0 ≤ b ≤ 10^18, 1 ≤ m ≤ 10^9). Đầu ra: aᵇ mod m.",tests:[{in:"3 13 1000",out:"323"},{in:"2 10 1000000007",out:"1024"},{in:"5 0 7",out:"1"},{in:"7 1000000000000000000 1",out:"0"},{in:"1000000000 1000000000000000000 999999937",out:"306034211"}],start:"#include <iostream>\nusing namespace std;\n\nlong long m;\n\nlong long luyThua(long long a, long long b) {\n    // a^b = (a^(b/2))^2, nhân thêm a nếu b lẻ; nhớ lấy mod sau mỗi phép nhân\n    return 1;\n}\n\nint main() {\n    long long a, b;\n    cin >> a >> b >> m;\n    cout << luyThua(a % m, b) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"3 "+n+" 1000000007",ns:[1000,1000000,1000000000],need:"logn",limit:n=>3000,why:"Nhân a với chính nó b lần là O(b), không thể với b = 10¹⁸. Chia đôi số mũ chỉ cần O(log b) lời gọi."},py:{start:"def luyThua(a, b, m):\n    # a^b = (a^(b//2))^2, nhân thêm a nếu b lẻ; nhớ lấy % m sau mỗi phép nhân\n    return 1\n\na, b, m = map(int, input().split())\nprint(luyThua(a % m, b, m))",hints:["Mỗi lời gọi chỉ gọi một lần với b // 2: khoảng 60 lời gọi cho b = 10¹⁸.","Lấy % m sau mỗi phép nhân để số không phình to. Python có sẵn pow(a, b, m) làm đúng việc này; hãy tự viết để hiểu."],needMsg:"Hãy tự viết hàm đệ quy luyThua, không dùng pow của Python.",need:/^(?![\s\S]*\bpow\s*\()/},cs:{start:"using System;\n\nclass Program\n{\n    static long m;\n\n    static long LuyThua(long a, long b)\n    {\n        // a^b = (a^(b/2))^2, nhân thêm a nếu b lẻ; nhớ lấy mod sau mỗi phép nhân\n        return 1;\n    }\n\n    static void Main()\n    {\n        long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long a = t[0], b = t[1];\n        m = t[2];\n        Console.WriteLine(LuyThua(a % m, b));\n    }\n}",hints:["Mỗi lời gọi chỉ gọi một lần với b / 2: khoảng 60 lời gọi cho b = 10¹⁸.","Lấy mod sau mỗi phép nhân: hai số < 10⁹ nhân nhau < 10¹⁸, vừa kiểu long. Điều kiện dừng trả về 1 % m (khi m = 1 thì kết quả là 0)."]}},{t:"Tháp Hà Nội",d:"Đầu vào: n (1 ≤ n ≤ 10). Đầu ra: dòng đầu là số bước ít nhất để chuyển n đĩa từ cọc A sang cọc C (dùng cọc B làm trung gian); các dòng sau, mỗi dòng một bước dạng “Dia k: X -> Y” theo đúng thứ tự của lời giải đệ quy chuẩn (chuyển n − 1 đĩa sang B, đĩa n sang C, n − 1 đĩa từ B sang C).",tests:[{in:"1",out:"1\nDia 1: A -> C"},{in:"2",out:"3\nDia 1: A -> B\nDia 2: A -> C\nDia 1: B -> C"},{in:"3",out:"7\nDia 1: A -> C\nDia 2: A -> B\nDia 1: C -> B\nDia 3: A -> C\nDia 1: B -> A\nDia 2: B -> C\nDia 1: A -> C"}],start:"#include <iostream>\nusing namespace std;\n\nvoid chuyen(int n, char tu, char den, char qua) {\n    // chuyển n - 1 đĩa sang cọc qua, chuyển đĩa n, rồi chuyển n - 1 đĩa sang cọc den\n}\n\nint main() {\n    int n;\n    cin >> n;\n    chuyen(n, 'A', 'C', 'B');\n    return 0;\n}",py:{start:"def chuyen(n, tu, den, qua):\n    # chuyển n - 1 đĩa sang cọc qua, chuyển đĩa n, rồi chuyển n - 1 đĩa sang cọc den\n    pass\n\nn = int(input())\nchuyen(n, \"A\", \"C\", \"B\")",hints:["Số bước là 2ⁿ − 1.","Khi chuyển n − 1 đĩa từ tu sang qua, cọc den đóng vai trung gian; và ngược lại ở lần gọi thứ hai."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Chuyen(int n, char tu, char den, char qua)\n    {\n        // chuyển n - 1 đĩa sang cọc qua, chuyển đĩa n, rồi chuyển n - 1 đĩa sang cọc den\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        Chuyen(n, 'A', 'C', 'B');\n    }\n}",hints:["Số bước là 2ⁿ − 1, tính bằng (1 << n) − 1.","Khi chuyển n − 1 đĩa từ tu sang qua, cọc den đóng vai trung gian; và ngược lại ở lần gọi thứ hai."]}}]);

makeQuiz("quiz20","score20",[{"q": "Hàm đệ quy thiếu điều kiện dừng sẽ dẫn tới?", "o": ["Trả về 0", "Lỗi biên dịch", "Gọi mãi tới khi tràn ngăn xếp", "Chạy chậm nhưng vẫn đúng"], "a": 2, "e": "Mỗi lời gọi chiếm thêm bộ nhớ ngăn xếp; không dừng thì bộ nhớ đó cạn."}, {"q": "fib(n) viết đệ quy trực tiếp có số lời gọi tăng theo?", "o": ["n", "n²", "hàm mũ (khoảng 1,6ⁿ)", "log n"], "a": 2, "e": "Mỗi lời gọi rẽ hai nhánh, cây phình theo hàm mũ."}, {"q": "Bộ nhớ ngăn xếp tối đa mà một hàm đệ quy dùng tỉ lệ với?", "o": ["Số lời gọi", "Độ sâu của cây lời gọi", "Số dòng code", "Giá trị trả về"], "a": 1, "e": "Cùng lúc chỉ có các lời gọi trên đường từ gốc tới nút đang chạy nằm trên ngăn xếp."}, {"q": "Tháp Hà Nội với 10 đĩa cần bao nhiêu bước?", "o": ["100", "512", "1023", "1024"], "a": 2, "e": "2¹⁰ − 1 = 1023."}]);

